export function mergeModelSettings(existing = {}, desired = {}) {
  const version = existing?.version ?? 1;
  const existingModels = existing && typeof existing === 'object' && existing.models && typeof existing.models === 'object'
    ? existing.models
    : {};

  const isPlainObject = (v) => v && typeof v === 'object' && !Array.isArray(v);

  const clone = (obj) => {
    try { return structuredClone(obj); } catch { return JSON.parse(JSON.stringify(obj)); }
  };

  const deepMerge = (target, source) => {
    if (!isPlainObject(source)) return clone(target ?? {});
    const out = isPlainObject(target) ? { ...target } : {};
    for (const [k, v] of Object.entries(source)) {
      if (isPlainObject(v) && isPlainObject(out[k])) {
        out[k] = deepMerge(out[k], v);
      } else {
        out[k] = v;
      }
    }
    return out;
  };

  const deepEqual = (a, b) => {
    if (a === b) return true;
    if (typeof a !== typeof b) return false;
    if (isPlainObject(a) && isPlainObject(b)) {
      const ka = Object.keys(a);
      const kb = Object.keys(b);
      if (ka.length !== kb.length) return false;
      for (const k of ka) {
        if (!Object.prototype.hasOwnProperty.call(b, k) || !deepEqual(a[k], b[k])) return false;
      }
      return true;
    }
    return false;
  };

  const baseModels = clone(existingModels);
  const newModels = clone(existingModels);

  for (const [fullId, desiredSettings] of Object.entries(desired || {})) {
    if (!isPlainObject(desiredSettings)) continue;
    const leaf = fullId.includes('/') ? fullId.split('/').pop() : fullId;
    const ids = fullId === leaf ? [fullId] : [fullId, leaf];
    for (const id of ids) {
      const existingEntry = isPlainObject(newModels[id]) ? newModels[id] : {};
      newModels[id] = deepMerge(existingEntry, desiredSettings);
    }
  }

  const changed = !deepEqual(baseModels, newModels);
  const settings = { version, models: newModels };
  return { settings, changed };
}

export function mergeModelSettings(existing, desired) {
  const version = existing?.version ?? 1;
  const baseModels = existing && typeof existing === 'object' && existing.models ? existing.models : {};

  const models = {};
  for (const [k, v] of Object.entries(baseModels)) {
    models[k] = JSON.parse(JSON.stringify(v));
  }

  let changed = false;
  const isPlainObject = v => v && typeof v === 'object' && !Array.isArray(v);

  const mergeObjects = (target, source) => {
    if (!target) return JSON.parse(JSON.stringify(source));
    if (!source) return target;
    const out = {};
    for (const k in target) out[k] = JSON.parse(JSON.stringify(target[k]));
    for (const k in source) {
      const tVal = target[k];
      const sVal = source[k];
      if (isPlainObject(tVal) && isPlainObject(sVal)) {
        out[k] = mergeObjects(tVal, sVal);
      } else {
        out[k] = JSON.parse(JSON.stringify(sVal));
      }
    }
    return out;
  };

  const deepEqual = (a, b) => JSON.stringify(a) === JSON.stringify(b);

  if (desired && typeof desired === 'object') {
    for (const [id, settings] of Object.entries(desired)) {
      const originalId = models[id];
      const mergedId = mergeObjects(originalId, settings);
      if (!deepEqual(mergedId, originalId)) changed = true;
      models[id] = mergedId;

      const parts = id.split('/');
      const leaf = parts.length > 1 ? parts[parts.length - 1] : id;
      if (leaf !== id) {
        const originalLeaf = models[leaf];
        const mergedLeaf = mergeObjects(originalLeaf, settings);
        if (!deepEqual(mergedLeaf, originalLeaf)) changed = true;
        models[leaf] = mergedLeaf;
      }
    }
  }

  return { settings: { version, models }, changed };
}

export function blockingErrors(results, editedFiles) {
  const errors = [];
  for (const { filePath, messages } of results ?? []) {
    if (!editedFiles.has(filePath)) continue;
    for (const { severity, ruleId, line, message } of messages ?? []) {
      if (severity === 2) {
        errors.push({ file: filePath, line, rule: ruleId, message });
      }
    }
  }
  errors.sort((a, b) => a.file.localeCompare(b.file) || a.line - b.line);
  return errors;
}

