export function blockingErrors(results, editedFiles) {
  const parseErrors = [];
  const normal = [];

  for (const { filePath, messages } of results ?? []) {
    const isEdited = editedFiles?.has(filePath);
    for (const msg of messages ?? []) {
      if (msg.severity !== 2) continue;
      const entry = {
        file: filePath,
        line: msg.line,
        rule: msg.ruleId,
        message: msg.message
      };
      if (msg.ruleId == null) {
        parseErrors.push(entry);
      } else if (isEdited) {
        normal.push(entry);
      }
    }
  }

  const parseByFile = new Map();
  for (const e of parseErrors) {
    if (!parseByFile.has(e.file)) parseByFile.set(e.file, []);
    parseByFile.get(e.file).push(e);
  }
  for (const [, arr] of parseByFile) {
    arr.sort((a, b) => a.line - b.line);
  }

  normal.sort((a, b) => {
    const fileCmp = a.file.localeCompare(b.file);
    if (fileCmp !== 0) return fileCmp;
    return a.line - b.line;
  });

  const merged = [];
  const files = new Set([...normal.map(x => x.file), ...parseByFile.keys()]);
  const sortedFiles = Array.from(files).sort((a, b) => a.localeCompare(b));

  for (const file of sortedFiles) {
    const p = parseByFile.get(file) ?? [];
    if (p.length) merged.push(...p);
    const n = normal.filter(x => x.file === file);
    if (n.length) merged.push(...n);
  }

  return merged;
}

