export function blockingErrors(results, editedFiles) {
  if (!Array.isArray(results)) return [];
  const out = [];

  for (const res of results) {
    if (!res?.filePath) continue;
    const msgs = Array.isArray(res.messages) ? res.messages : [];
    let parseErrors = [];
    let others = [];

    for (const msg of msgs) {
      if (msg.severity !== 2) continue;
      const entry = {
        file: res.filePath,
        line: msg.line,
        rule: msg.ruleId,
        message: msg.message
      };
      if (msg.ruleId === null) {
        parseErrors.push(entry);
      } else if (editedFiles.has(res.filePath)) {
        others.push(entry);
      }
    }

    for (const e of parseErrors) out.push({ ...e, _isParse: true });
    for (const e of others) out.push({ ...e, _isParse: false });
  }

  out.sort((a, b) => {
    if (a.file < b.file) return -1;
    if (a.file > b.file) return 1;
    if (a._isParse !== b._isParse) {
      return a._isParse ? -1 : 1;
    }
    return a.line - b.line;
  });

  return out.map(({ _isParse, ...rest }) => rest);
}
